import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"可靠性机制","description":"","frontmatter":{},"headers":[],"relativePath":"modules/kits/reliability.md","filePath":"modules/kits/reliability.md","lastUpdated":0}`),a={name:`modules/kits/reliability.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="可靠性机制" tabindex="-1">可靠性机制 <a class="header-anchor" href="#可靠性机制" aria-label="Permalink to “可靠性机制”">​</a></h1><p>EmakiKits 把&quot;不会重复发, 不会丢记录, 断电不坏档&quot;做成可检查的机制: 幂等键, 审计记录, 原子写与重启恢复. 本页给出机制说明与演示步骤, 服主可以自己验证</p><h2 id="幂等键防重复领取" tabindex="-1">幂等键防重复领取 <a class="header-anchor" href="#幂等键防重复领取" aria-label="Permalink to “幂等键防重复领取”">​</a></h2><p>每次领取 / 兑换 / 购买先登记一把幂等键, 登记成功才发放, 发放失败回滚:</p><table tabindex="0"><thead><tr><th>键形态</th><th>语义</th></tr></thead><tbody><tr><td><code>claim|&lt;礼包&gt;|&lt;玩家&gt;|&lt;周期&gt;</code></td><td>周期与一次性礼包每周期一次</td></tr><tr><td><code>cdk_global|&lt;兑换码&gt;</code></td><td><code>global_once</code> 兑换码全服一次</td></tr><tr><td><code>cdk_player|&lt;兑换码&gt;|&lt;玩家&gt;</code> 与 CDK 兑换计数</td><td><code>per_player_once</code> 按 <code>cdk.per_player_limit</code> 计次</td></tr><tr><td><code>bind|&lt;被邀请人&gt;</code></td><td>邀新绑定</td></tr><tr><td><code>milestone|...</code> / <code>selection|...</code></td><td>开启档位与自选记录</td></tr></tbody></table><p>重复领取 / 兑换的尝试直接拒绝: 玩家收到对应错误文案 (如 <code>error.kit.already_claimed</code>, <code>error.cdk.exhausted</code>), 控制台侧同时输出防重复日志, 不静默吞掉</p><h2 id="审计记录" tabindex="-1">审计记录 <a class="header-anchor" href="#审计记录" aria-label="Permalink to “审计记录”">​</a></h2><p>每个关键动作落一条审计 (玩家, 礼包, 动作, 事务号, 时间):</p><ul><li><code>/ekits inspect &lt;玩家名或 UUID&gt;</code> 查看玩家审计记录, 支持离线玩家</li><li>审计随 <code>data/store.yml</code> 持久化, 保留期由 <code>storage.retention.audit_days</code> 控制 (见<a href="./configuration.html">配置</a>)</li></ul><h2 id="原子写" tabindex="-1">原子写 <a class="header-anchor" href="#原子写" aria-label="Permalink to “原子写”">​</a></h2><p><code>data/store.yml</code> 保存走 tmp + move 原子替换 (<code>storage.atomic_writes: true</code>): 先写临时文件再整体替换, 中途断电不会留下半个文件</p><h2 id="重启恢复演示" tabindex="-1">重启恢复演示 <a class="header-anchor" href="#重启恢复演示" aria-label="Permalink to “重启恢复演示”">​</a></h2><ol><li>领取一个每日礼包, 用 <code>/ekits inspect</code> 确认审计记录已落</li><li>直接结束服务器进程 (模拟断电), 不走正常 stop</li><li>重启服务器, 对同一周期再次 <code>/ekits claim</code> → 应被拒 (already claimed)</li><li><code>/ekits inspect</code> 记录仍在, <code>data/store.yml</code> 完整可解析</li></ol><p>若第 3 步成功领到第二次, 属于缺陷, 请带 <code>data/store.yml</code> 与控制台日志反馈</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};